from tests_src import T, Q2, TF

T(28, "28-1", "The Lantern Stairs", "Narrative", [
"When Mika stepped off the sky-ferry, she discovered two things about Hollowmere that nobody had thought to mention. The first was that the town hung from the underside of a floating rock, its crooked houses dangling downwards like icicles. The second was that the stairs hummed, so that every step trembled faintly beneath her boots, as though the entire island were purring.",
"“You will grow accustomed to it,” said a tall man who was waiting at the landing, wearing a long coat fastened with brass buttons and carrying a pole tipped with a hook. “I am Mr Adeyemi, Keeper of the Lantern Stairs, and you must be my new apprentice.” Mika nodded, unable to speak; she had dreamed of this position for three weeks, and now that it had finally arrived, her mouth had turned as dry as chalk.",
"There were nine hundred lanterns in Hollowmere, and by tradition every one of them was lit by hand at the appearance of the first star. Mr Adeyemi passed her a small glass jar in which a single glow-moth fluttered, its wings flickering like a candle flame. “Hold the jar to the wick and ask the lantern to wake,” he explained. “Nothing more is required.” “Ask it?” said Mika. “Politely,” he replied, with the faintest twinkle.",
"She climbed to the first lantern and did precisely as she had been instructed, but nothing happened. She tried again, more loudly. By the tenth lantern her cheeks were burning; although she had a steady hand and had learned the lamplighting rhyme by heart, the lanterns stubbornly refused to obey her. Behind her, Mr Adeyemi said nothing at all, which was somehow far worse than any scolding could have been.",
"As dusk deepened, neighbours lingered on their doorsteps. Mika sank onto a step and rested her chin on her knees, and it was then that she noticed a small creature, no bigger than a teapot, huddled in the corner of the landing. Its fur was the silver-grey of rain clouds, and it was trembling. Forgetting her embarrassment, she broke her bread roll in half and held out a piece, murmuring as gently as she would to a nervous kitten. The creature sniffed, nibbled, and then crept into her lap, where it began to hum in exactly the same note as the stairs.",
"Something warm brushed her fingers. The nearest lantern had begun to glow, and one after another, all the way up the winding staircase, the rest bloomed into life like a slow tide of gold rising towards the sky. Mr Adeyemi stepped out of the shadows. “Lanterns have never listened to orders, and they care nothing for rhymes,” he said. “They wake only for someone who is calm and kind, and I could not be certain that you possessed that gift.” “Why didn’t you tell me?” asked Mika. “Had I done so, you would merely have pretended,” he said.",
"Mika looked down at the creature, which had fallen asleep with its nose tucked beneath its tail. “What shall I call him?” she whispered. “A stair-sprite chooses its own name,” said Mr Adeyemi, “but I rather suspect that he has already chosen you.”",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what does the phrase “grow accustomed to it” mean?",opts=["Become angry about it","Become curious about it","Become used to it","Become afraid of it"],a="C"),
 dict(d="2b",k="find",m=1,q="Find and copy the words that tell you what Mr Adeyemi’s coat was fastened with.",a="brass buttons",g="Accept “brass buttons” only."),
 dict(d="2b",k="short",m=1,q="How many lanterns were there in Hollowmere?",a="Nine hundred.",g="Accept 900."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The lanterns were lit when the first star appeared.","Mika lit the tenth lantern successfully.","The creature on the landing was trembling.","Mr Adeyemi scolded Mika when the lanterns stayed dark."],a=["T","F","T","F"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["The lanterns began to glow.","Mika arrived on the sky-ferry.","Mika shared her bread roll with a creature.","Mika failed to wake the first ten lanterns."],a=[4,1,3,2],g=Q2),
 dict(d="2d",k="short",m=1,q="Mr Adeyemi’s silence was “somehow far worse than any scolding could have been”. Why did Mika find his silence so hard to bear?",a="She could not tell what he was thinking / she felt he was judging her and had no help or advice.",g="Accept any answer showing Mika felt judged, worried or left without guidance. Do not accept “he was angry” alone."),
 dict(d="2d",k="mc",m=1,q="What does paragraph 4 suggest about how Mika was feeling?",opts=["Proud of how well she was doing","Angry with Mr Adeyemi","Bored with her new job","Embarrassed and worried that she was failing"],a="D"),
 dict(d="2g",k="short",m=1,q="The author says the lanterns “bloomed into life like a slow tide of gold”. What does this description suggest about the way the lanterns lit up?",a="They lit up gradually and smoothly, one after another, in a beautiful way.",g="Accept any answer about slowly spreading light, a gentle flowing movement, or beauty (like flowers opening or a tide rising)."),
 dict(d="2d",k="short",m=2,q="Give two clues from paragraph 5 that show the creature needed care.",a="It was trembling; it was huddled in a corner (alone); it nibbled the bread (hungry).",g="1 mark for each clue. Accept: trembling / huddled in a corner / small / nibbled the bread. Max 2."),
 dict(d="2d",k="short",m=1,q="Why do you think the lanterns lit for Mika only after she had helped the creature?",a="Lanterns wake for people who are calm and kind, and Mika showed kindness to the creature.",g="Accept any answer linking the lanterns lighting to Mika being kind or calm. Do not accept “the creature lit them” alone."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the message of the story?",opts=["Kindness matters more than following instructions perfectly.","Lanterns are difficult to light.","It is best to keep secrets from other people.","Apprentices should never ask questions."],a="A"),
 dict(d="2a",k="find",m=1,q="Find and copy one word from paragraph 5 that means shaking slightly.",a="trembling",g="Accept “trembling” only."),
 dict(d="2e",k="short",m=1,q="What do you think Mika will do when the first star appears tomorrow? Give a reason from the story.",a="She will light the lanterns, because she now knows they wake for someone calm and kind.",g="Accept any sensible prediction that is supported by the text (for example she will be calm and kind, or she will bring the creature with her)."),
 dict(d="2d",k="short",m=1,q="Why did Mr Adeyemi not tell Mika the secret of the lanterns at the start?",a="If he had, she would only have pretended to be kind / it would not have been real.",g="Accept any answer saying she would have pretended, or that the kindness had to be real."),
])

T(28, "28-3", "The Grandad Decision", "Narrative", [
"The letter from school arrived on Monday morning, and Marcus read it three times before he could believe it. He had been selected for the chess team that would compete in the county final on Saturday. For two years he had practised on the bus, at lunchtime and beneath his bedcovers with a torch, and at last all that quiet determination had been noticed.",
"Then Mum came in from the kitchen, drying her hands on a tea towel. “Don’t forget Saturday, Marcus. It’s Grandad’s eightieth birthday, and we’re all meeting at the restaurant at twelve; Auntie Grace is even travelling up from Cornwall for it.” Marcus’s stomach lurched with dismay. The final began at ten and might well continue until after one o’clock, so there was no possible way of attending both.",
"That night he lay awake, staring at the ceiling. Mrs Okafor, his teacher, had told him that the team could not manage without him, for there were only five players and he was the strongest of them. Yet Grandad was the person who had first taught him to play, on a wobbly board where two missing pawns had been replaced by buttons. Every Sunday afternoon they had sat at the kitchen table while the kettle whistled, and Grandad had never once allowed him to win.",
"On Tuesday he tried to banish the problem from his mind, and on Wednesday he tried again. Then he compiled a list. In one column he wrote his reasons for playing: the trophy, the team, the chance to prove himself. In the other he wrote a single word: Grandad. He studied the two columns for a long while. One was long and one was short, and yet, oddly, the short one seemed to weigh far more.",
"On Thursday he went to Mrs Okafor’s classroom, his palms sticky. “I can’t play on Saturday,” he blurted. “It’s my grandad’s birthday.” She was silent for a moment, and Marcus braced himself. “I am disappointed, and I won’t pretend otherwise,” she said at last. “But I would think less of you if you had chosen differently. We shall ask Jin to take your place; he has been progressing steadily all term.” Relief and sadness swirled together inside Marcus like paint in water.",
"At the restaurant on Saturday, Grandad’s face crinkled into a smile when Marcus walked in, then slowly into a frown. “Shouldn’t you be at the tournament?” he asked. “I swapped with someone,” said Marcus, handing over a small parcel. Grandad shook his head. “You gave up your final for an old man’s lunch?” “It isn’t just lunch,” said Marcus. “You taught me everything I know.” Grandad cleared his throat and studied the tablecloth. When at last he spoke, his voice was gruff. “Best present I’ve ever had,” he said, “and I haven’t even opened it.”",
"At half past two, a message buzzed on Mum’s phone: the team had finished third, and Jin had won his final game. Marcus read it twice and smiled, surprised to find that it did not feel like losing. Grandad, meanwhile, had already set up a small travelling chess set beside the birthday cake. “Now,” he said, with a twinkle, “shall we discover whether you have improved?”",
], [
 dict(d="2b",k="short",m=1,q="When was the county final going to be played?",a="On Saturday morning.",g="Accept Saturday / Saturday morning at ten o’clock."),
 dict(d="2a",k="mc",m=1,q="In paragraph 5, what does the phrase “braced himself” mean?",opts=["Held onto the desk","Got ready for bad news","Stood up straight to leave","Started to feel proud"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the words that tell you where Marcus practised chess at night.",a="beneath his bedcovers with a torch",g="Accept “beneath his bedcovers” with or without “with a torch”."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The final started at ten o’clock.","Auntie Grace lived very close to the restaurant.","Grandad was the person who first taught Marcus to play chess.","Marcus was the weakest player on the team."],a=["T","F","T","F"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["Marcus gave Grandad a present.","Mum reminded Marcus about the birthday.","Marcus told Mrs Okafor his decision.","Marcus opened the letter from school."],a=[4,2,3,1],g=Q2),
 dict(d="2d",k="short",m=1,q="Why did Marcus’s stomach lurch when Mum spoke about Saturday?",a="He realised that the chess final and the birthday lunch clashed, and he could not do both.",g="Accept any answer showing he realised the two events were at the same time."),
 dict(d="2d",k="short",m=1,q="One column of Marcus’s list was long and one was short, but “the short one seemed to weigh far more”. What does this tell you about how Marcus felt?",a="Grandad mattered more to him than all the reasons for playing put together.",g="Accept any answer showing that Grandad was the most important thing to him."),
 dict(d="2g",k="short",m=1,q="The author says relief and sadness “swirled together … like paint in water”. What does this show about Marcus’s feelings?",a="He felt both feelings at once and they were mixed up together.",g="Accept any answer about mixed, confused or blended feelings."),
 dict(d="2d",k="short",m=1,q="How can you tell that Mrs Okafor respected Marcus’s decision even though she was disappointed?",a="She said she would think less of him if he had chosen differently / she quickly arranged for Jin to take his place.",g="Accept either piece of evidence."),
 dict(d="2d",k="mc",m=1,q="How did Grandad feel when he heard why Marcus was at the restaurant?",opts=["Cross that Marcus had missed the final","Annoyed with Mum","Deeply touched","Bored of chess"],a="C"),
 dict(d="2b",k="short",m=2,q="Give two things that Marcus and Grandad did together when Marcus was learning to play chess.",a="They sat at the kitchen table on Sunday afternoons; they used buttons in place of missing pawns; Grandad never let him win.",g="1 mark for each. Accept any two of: played every Sunday afternoon at the kitchen table / used buttons for missing pawns / Grandad never let Marcus win. Max 2."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the story?",opts=["Marcus chooses his grandfather’s birthday over an important chess final.","Marcus wins the county chess final.","Marcus is angry with his teacher.","Grandad forgets his own birthday."],a="A"),
 dict(d="2e",k="short",m=1,q="What do you think Marcus and Grandad will do next? Use the text to help you.",a="They will play chess together at the table.",g="Accept any answer about playing chess, supported by the travelling chess set or Grandad’s challenge."),
 dict(d="2g",k="find",m=1,q="Find and copy the two words that show how Marcus’s hands felt when he went to see Mrs Okafor.",a="palms sticky",g="Accept “palms sticky” or “sticky palms”. Both words are needed."),
])

T(28, "28-5", "The Glass Workshop", "Description", [
"The workshop door was so heavy that Uncle Femi had to lean his whole weight against it, and when it finally swung open, a wave of heat rolled over me as though someone had pressed a hot palm against my face. Inside, the room was dim except for a round furnace at its centre, which glowed a fierce, dazzling orange and roared with a deep, steady sound like a lion purring in its sleep. Somewhere in the gloom a radio was playing, though I could hardly hear it above the noise.",
"“Stay behind the yellow line, Amara,” said Uncle Femi, pulling on a pair of thick leather gloves. Shelves lined every wall, crowded with glass animals, twisted bottles and jugs in the colours of sea and sunset, and wherever the light from the furnace touched them, they shimmered as though they were alive. The air smelt of hot metal and something sweet, like burnt sugar.",
"He lowered a long steel pipe into the furnace, twirled it slowly like a spoon in a jar of honey, and lifted out a blob of molten glass that sagged and stretched, so luminous that I had to squint. Uncle Femi never stopped turning the pipe, not even for a moment. “If I stop, it will droop and fall,” he said. “Glass is patient, but it isn’t kind.”",
"He rolled the blob through a tray of crushed blue glass until it glittered like frost, then raised the pipe to his lips and blew. I held my breath as the glass swelled into a bubble, as delicate as a soap bubble yet glowing like a small sun. He pressed a wad of wet newspaper against it to coax it into shape, and the paper hissed and puffed out clouds of steam. His hands, which looked so rough and clumsy at home, moved with the sure, steady precision of a surgeon’s.",
"Next, he took a pair of long tweezers and pinched the bubble to make a neck, then tugged out a thin curl for a tail, and slowly a bird emerged, with a small round body, a lifted head and a tail that swept like a feather. Every few moments he returned it to a smaller furnace, which he called the glory hole, to keep it pliable; the name made me smile. He worked without hurrying and without speaking, as composed as a cat watching a window.",
"At last he tapped the bird gently from the pipe and set it inside a long oven. “It has to cool slowly, overnight,” he explained, “because if it cools too quickly, it will crack.” Through the little window I watched the bird glow dull red, then orange, then fade to a deep, clear blue, with a single tiny bubble trapped in its chest like a heart.",
"The workshop grew quiet. Sweat trickled down Uncle Femi’s face, and he wiped it away with his sleeve and grinned. “Come back in the morning,” he said. “It’s yours.” The glass animals on the shelves seemed to watch me leave, their eyes glinting in the firelight, and I could hardly sleep that night for wondering what the morning would bring.",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does the word “fierce” suggest about the glow of the furnace?",opts=["Faint and flickering","Strong and intense","Cool and calm","Blue and cold"],a="B"),
 dict(d="2d",k="short",m=1,q="Why do you think Amara was told to stay behind the yellow line?",a="For safety, because the furnace and glass were extremely hot.",g="Accept any answer about keeping safe from the heat or danger."),
 dict(d="2b",k="find",m=1,q="Find and copy the words that describe what the air smelt of in the workshop.",a="hot metal and something sweet",g="Accept “hot metal and something sweet”. Do not accept “burnt sugar” alone."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The furnace was in the centre of the workshop.","Uncle Femi stopped turning the pipe while he was talking.","The glass bird was cooled quickly in cold water.","Wet newspaper was used to shape the glass."],a=["T","F","F","T"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["He blew into the pipe.","He set the bird in an oven to cool.","He lifted out a blob of molten glass.","He pinched a neck and pulled out a tail."],a=[2,4,1,3],g=Q2),
 dict(d="2g",k="short",m=1,q="Uncle Femi twirled the pipe “like a spoon in a jar of honey”. What does this tell you about the molten glass?",a="It was thick and slow-moving / sticky.",g="Accept: thick, sticky, slow or gloopy."),
 dict(d="2b",k="short",m=1,q="Why did Uncle Femi have to keep turning the pipe?",a="If he stopped, the glass would droop and fall.",g="Accept: so the glass would not droop or fall."),
 dict(d="2d",k="short",m=1,q="Amara says her uncle’s hands moved with “the sure, steady precision of a surgeon’s”. What does this tell you about him?",a="He was very skilled and careful when he worked.",g="Accept any answer about skill, care, precision or confidence."),
 dict(d="2d",k="short",m=2,q="Give two pieces of evidence that Amara admired her uncle’s work.",a="She held her breath; the name “glory hole” made her smile; she compared his hands to a surgeon’s; she could hardly sleep that night.",g="1 mark for each. Accept any two relevant pieces of evidence from the text. Max 2."),
 dict(d="2b",k="short",m=1,q="Why did the bird have to cool slowly overnight?",a="If it cooled too quickly, it would crack.",g="Accept: to stop it cracking."),
 dict(d="2a",k="find",m=1,q="Find and copy one word from paragraph 3 that means “melted”.",a="molten",g="Accept “molten” only."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up paragraph 5?",opts=["Uncle Femi gets tired and stops work.","Uncle Femi shapes the glass into a bird and warms it again when needed.","Amara asks how glass is made.","The bird falls and breaks on the floor."],a="B"),
 dict(d="2d",k="short",m=1,q="Uncle Femi says, “Glass is patient, but it isn’t kind.” What do you think he means?",a="Glass will wait while you work, but it will punish mistakes (for example, if you stop turning it, it will fall).",g="Accept any answer that shows glass allows time but will not forgive mistakes or is hard to work with."),
 dict(d="2e",k="short",m=1,q="What do you think Amara will do in the morning? Give a reason.",a="She will go back to collect the glass bird, because her uncle said it would be hers.",g="Accept any sensible answer linked to collecting the bird."),
])

T(29, "29-2", "The Slow River", "Narrative", [
"Kofi dug his paddle into the water as though he were trying to leave the river behind him. In the middle of the canoe, his sister Efua sat with a map spread across her knees, humming quietly to herself, while ahead the river slid between banks of bending willows, brown and glossy as melted chocolate. They had been travelling since dawn, and Kofi had been counting the minutes ever since.",
"“Steady, Kofi,” called Aunt Yaa from the stern, where she steered. She was a river ranger who had spent months planning this three-day trip, and she knew every bend of the water. “We aren’t racing anyone.” “But we’re supposed to reach the lake by evening,” Kofi protested. “We shall get there when we get there,” said his aunt, and he could hear from her voice that she was smiling. The morning mist had long since lifted, and the water glittered in the sunshine.",
"Kofi did not answer. For the next hour he paddled harder than ever, jaw set, ignoring the blisters that stung his palms and the ache that crept across his shoulders. Spray splashed his face, and twice the canoe scraped against a hidden stone, but he was so intent on speed that he failed to notice the hush settling over the water until Efua laid a hand on his shoulder. “Kofi. Stop paddling. Look.”",
"He turned, scowling. On a branch that overhung the water, barely an arm’s length away, perched a small bird with a back the colour of a summer sky and a chest like a glowing ember. A kingfisher. It regarded them with perfect composure, quite unafraid, and then it plunged, a flash of blue, and rose again with a silver fish glittering in its beak.",
"Kofi’s mouth fell open. He would have swept straight past it. All morning, he realised, he had been so preoccupied with getting somewhere that he had never once noticed where he was. Now that the canoe drifted, the river came alive around him: dragonflies hovered like tiny helicopters, a heron stood as motionless as a statue in the shallows, and the reeds whispered and rustled with hidden things.",
"“The river keeps its secrets,” said Aunt Yaa, resting her paddle across her knees, “for those who travel slowly enough to discover them.” Efua raised an eyebrow. “You knew he would rush.” “Everyone rushes at first,” said Aunt Yaa. “I did. Some lessons are worth far more when you find them out for yourself.” Kofi felt his ears grow hot, but he found, to his surprise, that he was grinning.",
"They reached the lake long after sunset, when the sky had turned the colour of plums and the first stars were pricking through the darkness. Kofi did not mind in the slightest. He sat on the shore with a torch and his notebook, in which he had drawn, for the very first time, a kingfisher, and beneath it, in careful letters, he wrote: Arrived late. Worth it.",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 5, what does the word “preoccupied” mean?",opts=["Frightened","Mainly thinking about one thing","Very tired","Pleased with himself"],a="B"),
 dict(d="2b",k="short",m=1,q="What is Aunt Yaa’s job?",a="She is a river ranger.",g="Accept river ranger."),
 dict(d="2b",k="find",m=1,q="Find and copy the words that describe the colour of the kingfisher’s back.",a="the colour of a summer sky",g="Accept “the colour of a summer sky” or “summer sky”."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The trip was planned to last three days.","Aunt Yaa steered from the stern of the canoe.","Efua was holding the map.","The kingfisher flew away as soon as it saw the canoe."],a=["T","T","T","F"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in the story.",items=["The kingfisher caught a fish.","Kofi paddled harder and harder.","The family reached the lake after sunset.","Efua told Kofi to stop and look."],a=[3,1,4,2],g=Q2),
 dict(d="2d",k="short",m=1,q="Why was Kofi paddling so hard?",a="He wanted to reach the lake by evening / he was impatient to arrive.",g="Accept any answer about wanting to get to the lake quickly."),
 dict(d="2d",k="short",m=2,q="How can you tell that Kofi was in a bad mood before he saw the kingfisher? Give a point and support it with evidence from the text.",a="He was annoyed or stubborn: he did not answer his aunt, he paddled with his jaw set, ignored his blisters, or turned round scowling.",g="1 mark for a suitable point (annoyed, stubborn, grumpy, determined). 1 mark for evidence (did not answer / jaw set / ignoring blisters / scowling)."),
 dict(d="2g",k="short",m=1,q="The kingfisher “plunged, a flash of blue”. Why has the author chosen the word “flash”?",a="To show that the bird moved very quickly and was brightly coloured.",g="Accept any answer about speed or brightness."),
 dict(d="2g",k="short",m=1,q="The dragonflies “hovered like tiny helicopters”. What does this simile show about the dragonflies?",a="They stayed in the air in one place, with buzzing, whirring wings.",g="Accept any answer about hovering, whirring wings or being small."),
 dict(d="2d",k="short",m=1,q="In paragraph 5, what did Kofi realise about the way he had been travelling?",a="He had been so keen to arrive that he had not noticed anything around him.",g="Accept any answer about being so focused on the destination that he missed what was around him."),
 dict(d="2d",k="short",m=1,q="Why do you think Aunt Yaa let Kofi discover the kingfisher for himself, instead of simply telling him to slow down?",a="She believed a lesson matters more when you find it out for yourself.",g="Accept any answer based on “lessons are worth far more when you find them out for yourself”."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the message of the story?",opts=["Canoes are faster than walking.","The journey can matter as much as arriving.","Younger children always know best.","Fish are easy to catch."],a="B"),
 dict(d="2b",k="short",m=1,q="What colour was the sky when they reached the lake?",a="The colour of plums (purple).",g="Accept plum / purple / the colour of plums."),
 dict(d="2e",k="short",m=1,q="How do you think Kofi will paddle for the rest of the trip? Give a reason from the story.",a="More slowly and calmly, because he has learned to notice what is around him.",g="Accept any sensible prediction supported by his change of attitude."),
])

T(29, "29-3", "Room for Everyone", "Exposition", [
"Somewhere in your town there is a building where anyone can walk in, borrow almost anything they like and walk out again without paying a penny. It is not a shop, and it has no shareholders or advertisements. It is a library, and I firmly believe that it is one of the most valuable places a community can possess. Information is now available on every phone, so some people wonder whether libraries are still necessary. I intend to show that they are.",
"First, a library gives everybody an equal chance to read. Books are expensive, and a family that must count every pound cannot always afford a shelf of them. A library removes that barrier entirely. A child who borrows an adventure story on Saturday has exactly the same choice as a child whose parents buy new books every week. Studies have often found that pupils who read for pleasure tend to do better in school across all subjects, not simply in English.",
"Second, libraries offer far more than books. Many lend newspapers, audiobooks, films and computers, and most run clubs, workshops and story sessions for people of every age. Some provide a quiet desk for a student who has no space to study at home, and others help elderly visitors to send their first email. A library is, in short, a shared classroom that welcomes every newcomer.",
"Third, libraries are staffed by people who know how to find things out. A librarian can guide a reluctant reader towards a book that suddenly makes reading enjoyable, or show a researcher how to judge whether a website can be trusted. On the internet, anybody may publish anything, and the truth is often buried beneath rumour. Skilled guidance in sorting reliable facts from careless claims is more useful now than ever.",
"Fourth, a library is a place where people meet. Neighbours who might never otherwise speak sit at adjoining tables, and a shy child may make a first friend over a shared love of dragons. We spend more and more time alone with our screens. A welcoming public space that asks nothing in return is therefore rare, and it strengthens the bonds that hold a community together.",
"Some people object that libraries cost taxpayers money and that everything can be found online. It is true that running a library is not free. However, the cost is small when it is shared among everyone. The return is enormous, because each book may be borrowed dozens of times. Moreover, not every household has a reliable internet connection, and a screen cannot recommend a book or greet a visitor with a smile.",
"In conclusion, a library offers fairness, learning, trustworthy guidance and friendship, all beneath a single roof. If we allow such places to fade away, we will lose something that is hard to rebuild. Surely a community that values its children should protect the one building that opens its doors to every one of them? Let us use our libraries, defend them and, above all, keep them busy.",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what does the word “barrier” mean?",opts=["A cheap price","A helpful rule","Something that blocks the way","A kind of shelf"],a="C"),
 dict(d="2b",k="short",m=1,q="What does the author say they intend to show?",a="That libraries are still necessary.",g="Accept any answer about libraries still being needed or valuable today."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The author says libraries lend more than books.","The author says a library charges a small fee to borrow a book.","The author says a librarian can help people judge whether a website can be trusted.","The author says every household has a reliable internet connection."],a=["T","F","T","F"],g=TF),
 dict(d="2g",k="find",m=1,q="Find and copy the three words in paragraph 6 that show the author accepts that people who disagree have a fair point.",a="It is true",g="Accept “It is true”."),
 dict(d="2c",k="order",m=1,q="Number the points from 1 to 4 to show the order in which the author makes them.",items=["Libraries are places where people meet.","Libraries give everyone an equal chance to read.","Librarians help people to find things out.","Libraries offer more than books."],a=[4,1,3,2],g=Q2),
 dict(d="2d",k="short",m=2,q="Why does the author think a library is fairer than buying books? Use evidence from paragraph 2.",a="Everyone can borrow the same books, whatever their family can afford; a child who borrows has the same choice as one whose parents buy new books every week.",g="1 mark for the idea that a library gives everyone the same access whatever their money. 1 mark for supporting evidence (a family that counts every pound cannot afford a shelf of books / same choice on Saturday)."),
 dict(d="2g",k="short",m=1,q="Why do you think the author begins by describing a building where anyone can “borrow almost anything they like” without paying?",a="To make the reader curious and to show how generous a library is before naming it.",g="Accept any answer about arousing curiosity, holding attention or showing that a library is free and open."),
 dict(d="2b",k="short",m=2,q="Give two things, other than books, that many libraries lend.",a="Newspapers; audiobooks; films; computers.",g="1 mark for each. Accept any two of: newspapers, audiobooks, films, computers. Max 2."),
 dict(d="2g",k="short",m=1,q="The author ends with a question: “Surely a community that values its children should protect the one building that opens its doors to every one of them?” What is the effect of this question?",a="It makes the reader think and encourages them to agree that libraries should be protected.",g="Accept any answer about persuading, involving the reader or making the argument seem obvious."),
 dict(d="2d",k="short",m=1,q="Why might a library be especially helpful to a student with no space to study at home?",a="It provides a quiet desk where the student can work.",g="Accept any answer about a quiet place or desk to study."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up paragraph 4?",opts=["Librarians help people to find good books and reliable facts.","Librarians work only with young children.","The internet contains no useful information.","Researchers should avoid websites."],a="A"),
 dict(d="2a",k="find",m=1,q="Find and copy one word from paragraph 4 that means “unwilling”.",a="reluctant",g="Accept “reluctant” only."),
 dict(d="2d",k="short",m=2,q="Give one objection to libraries from paragraph 6 and explain how the author answers it.",a="Objection: they cost taxpayers money / everything is online. Answer: the cost is shared and each book is borrowed many times; not every household has a reliable internet connection.",g="1 mark for a valid objection (cost, or everything can be found online). 1 mark for the author’s reply (cost shared and returns enormous / books borrowed many times / not everyone has internet)."),
 dict(d="2e",k="short",m=1,q="What do you think the author would say to someone who wanted to close the local library?",a="That it would be a serious loss that is hard to rebuild, because libraries offer fairness, learning, guidance and friendship.",g="Accept any answer that draws on paragraph 7 or the earlier points."),
])

T(29, "29-4", "The Lemon Battery", "Recount (Fictional)", [
"By half past eight on the morning of the Science Fair, my hands were already trembling. I stood behind my table in the school hall, surrounded by cardboard rockets and wobbling papier-mâché planets, staring at my project, which bore a very long title that I had copied out in my best handwriting: “Can Fruit Make Electricity?” I had spent two weeks preparing it, and I was quite convinced that it was brilliant.",
"The idea was simple. I had pushed a zinc-coated nail and a strip of copper into each of four lemons, then joined them in a chain with crocodile clips and wires. The juice inside a lemon is acidic, and when it touches two different metals, it produces a tiny electric current; four lemons together, I had read, should generate enough to light a small LED bulb. At home the experiment had worked perfectly, and my little brother had cheered so loudly that the dog next door began to bark.",
"But at ten o’clock, with the judges due at any minute, I connected the final wire and … nothing. The bulb stayed dark. I checked every clip, squeezed each lemon and even whispered encouragement. My best friend, Callum, wandered over from the next table and peered doubtfully at my display. “Maybe they’re not ripe,” he suggested. “Lemons aren’t ripe or unripe, Callum,” I hissed. “They’re just sour.”",
"Panic turned my fingers icy. The judges had already reached the table two along, where a boy was demonstrating a robot arm made from cardboard, when Mr Brennan, my teacher, strolled past and glanced at my display, at the dark bulb and at my face. “Problem?” he asked. I explained everything in one long breath. He did not touch a single wire. “Electricity is a bit like some people, Ines,” he said thoughtfully. “It can be very particular about which way round it likes to go.” And off he wandered, whistling.",
"I stared at the bulb. Then, slowly, a fact from my research surfaced from the back of my mind: an LED has two legs, and current will flow through it in one direction only. The evening before, when I had packed up my display, I must have disconnected the bulb and later replaced it the wrong way round. With shaking fingers I unclipped it and swapped its legs over, and it burst into a bright, steady glow. I gasped so loudly that Callum dropped his pencil case.",
"The judges arrived a minute later, and this time I explained everything calmly: the metals, the acid, the chain of lemons and the LED. When one of them asked what I had learned, I told her the truth. “That a project not working is only a problem until you find out why.” She smiled and wrote something on her clipboard.",
"I did not win; first prize went to Aisha, whose fan was powered by the sun. But before I left, Mr Brennan pinned a certificate to my display that read Best Problem Solver. As I carried my lemons home in a carrier bag, I decided that, in some ways, it was even better.",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does the word “convinced” mean?",opts=["Worried","Bored","Surprised","Completely sure"],a="D"),
 dict(d="2b",k="short",m=1,q="How many lemons did Ines use in her project?",a="Four.",g="Accept 4 / four."),
 dict(d="2b",k="find",m=1,q="Find and copy the title of Ines’s project.",a="Can Fruit Make Electricity?",g="Accept “Can Fruit Make Electricity?”. The question mark is not needed."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The judges had already visited Ines’s table when the bulb failed.","An LED will only work when current flows through it one way.","Callum suggested that the lemons were not ripe.","Ines won first prize."],a=["F","T","T","F"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Ines swapped the legs of the bulb.","The judges arrived at Ines’s table.","Ines connected the last wire and nothing happened.","Mr Brennan gave Ines a hint about electricity."],a=[3,4,1,2],g=Q2),
 dict(d="2d",k="short",m=1,q="Why had Ines expected her project to work at the Science Fair?",a="It had worked perfectly at home.",g="Accept any answer about it working at home or her research."),
 dict(d="2d",k="short",m=1,q="Why do you think Ines “hissed” her reply to Callum?",a="She was stressed and annoyed, and did not want the judges to overhear.",g="Accept any answer about her being tense, annoyed or worried about being overheard."),
 dict(d="2d",k="short",m=2,q="What was wrong with Ines’s circuit? Use evidence from paragraph 5 to support your answer.",a="The LED bulb was the wrong way round; when she swapped its legs, it lit up.",g="1 mark for the LED being connected the wrong way round. 1 mark for evidence: she swapped its legs over and it glowed / an LED works in one direction only."),
 dict(d="2d",k="short",m=1,q="Why do you think Mr Brennan gave Ines a hint instead of fixing the problem himself?",a="He wanted her to work it out herself and learn from it.",g="Accept any answer about letting her learn, think or solve it independently."),
 dict(d="2g",k="short",m=1,q="The bulb “burst into a bright, steady glow”. What does the word “burst” suggest about the way the light came on?",a="It came on suddenly and brightly.",g="Accept: suddenly, quickly, all at once."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the story?",opts=["Ines’s experiment fails until she works out why, and she learns from it.","Ines wins the Science Fair with a fan.","Callum ruins Ines’s project.","Lemons cannot make electricity."],a="A"),
 dict(d="2a",k="find",m=1,q="Find and copy one word from paragraph 4 that means “walked in a relaxed way”.",a="strolled",g="Accept “strolled” only."),
 dict(d="2d",k="short",m=2,q="What do you think Ines learned from the Science Fair? Explain using evidence from the text.",a="That it is important to work out why something has failed, and not to give up; she says a project not working is only a problem until you find out why.",g="1 mark for a sensible lesson (problem solving, staying calm, checking carefully). 1 mark for evidence from paragraphs 5 to 7 (her answer to the judge, the certificate, or how she fixed it)."),
 dict(d="2e",k="short",m=1,q="If another project stopped working, what do you think Ines would do first? Give a reason.",a="Check how the parts are connected, because she now knows that a small mistake can stop things working.",g="Accept any sensible prediction linked to checking the circuit, staying calm or working out why."),
])

T(29, "29-5", "Thunder on the Moor", "Description", [
"All afternoon the moor had lain beneath a heavy, breathless heat, its heather faded to the dull purple of an old bruise. Not a breath of wind stirred the bracken. Skylarks that had sung since morning fell silent one by one, and even the sheep, scattered like grey pebbles across the slope, huddled together beside the crumbling wall. From the doorway of the old stone barn, where Dad and I had stopped to shelter, I watched the horizon turn from blue to slate.",
"The clouds arrived slowly, piling upon one another like dark mountains and swallowing the sun in a single, silent gulp. Their edges glowed a sickly yellow, and beneath them the light thinned to a strange green-grey that turned every rock and gorse bush flat and colourless. The air smelt of hot dust and something metallic, as if the whole sky were a coin held against the tongue.",
"Then, without warning, the first gust swept across the heather, and the whole hillside shivered. Grass flattened in long, rippling waves. A carrier bag, snatched from nowhere, tumbled past the barn and vanished over the wall. The temperature dropped so suddenly that I pulled my sleeves down over my hands, and a low, grumbling rumble rolled across the valley, like furniture being dragged across a distant floor.",
"A fork of lightning split the horizon, so vivid that for an instant every stone and stalk stood out in sharp white detail, printed on my eyes long after the light had gone. I began to count, as Dad had taught me: one, two, three, four, five. The thunder cracked overhead, so loud that I felt it in my ribs, and then it rolled away, muttering, into the hills. “Five seconds,” said Dad quietly. “About a mile off. It’s still coming.”",
"The rain followed at once. It began with a few heavy drops that struck the dry earth and raised little puffs of dust, then thickened into a roaring curtain that hid the far hills completely. Water hammered on the barn roof, ran in silver ropes from the slates and swelled the ruts of the track into brown, chattering streams. The smell of wet earth and crushed heather rose all around us, rich and sweet, and I breathed it in until my chest ached.",
"For a quarter of an hour the storm circled the moor as though it had lost something and was searching for it. Lightning flickered, thunder muttered, and the sheep bleated in protest. Then, gradually, the gaps between flash and rumble stretched longer, the rain softened to a whisper, and the great clouds began to slide eastwards, trailing grey veils behind them.",
"A last shaft of sunlight broke through and lit the wet heather so that it blazed with purple fire, and every blade of grass was strung with drops, like beads of glass. Somewhere above us a skylark tried one uncertain note, then another, and at last poured out its song. “Come on,” said Dad, smiling and shaking the water from his hair. “Let’s see what the moor looks like now.”",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does the word “breathless” suggest about the heat?",opts=["Fast and noisy","Still and airless","Cold and damp","Sudden and violent"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the words that compare the sheep to something on the slope.",a="like grey pebbles",g="Accept “like grey pebbles” or “grey pebbles”."),
 dict(d="2b",k="short",m=1,q="Where were the narrator and Dad sheltering?",a="In the doorway of an old stone barn.",g="Accept: a (stone) barn."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The skylarks kept singing as the clouds gathered.","The temperature dropped suddenly when the first gust arrived.","The narrator counted five seconds after the lightning flash.","The storm passed over the moor in a few moments without circling."],a=["F","T","T","F"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Rain fell in a roaring curtain.","Clouds swallowed the sun.","The narrator counted after a flash of lightning.","A gust of wind swept across the heather."],a=[4,1,3,2],g=Q2),
 dict(d="2d",k="short",m=2,q="Give two clues in paragraph 1 that the weather was about to change.",a="Not a breath of wind stirred; the skylarks fell silent; the sheep huddled together; the horizon turned slate-coloured; the heat was heavy.",g="1 mark for each clue. Accept any two of: no wind, skylarks silent, sheep huddled, horizon darkening, heavy heat. Max 2."),
 dict(d="2g",k="short",m=1,q="The author says the air smelt as if “the whole sky were a coin held against the tongue”. What does this suggest about the air?",a="It had a sharp, metallic smell or taste.",g="Accept any answer about a metallic, sharp or strange smell or taste."),
 dict(d="2g",k="short",m=1,q="The thunder rolled away, “muttering, into the hills”. Why is “muttering” an effective word choice?",a="It suggests a low, grumbling sound, like someone talking under their breath, that fades away.",g="Accept any answer about a low, grumbling or fading sound, or thunder being given human qualities."),
 dict(d="2d",k="short",m=1,q="Dad says, “It’s still coming.” Why does he say this?",a="Five seconds means the storm is about a mile off, so it has not yet reached them and is getting closer.",g="Accept any answer linking the count to the storm still being some way off but approaching."),
 dict(d="2d",k="short",m=2,q="How does the author show that the rain was very heavy? Give a point and support it with evidence from paragraph 5.",a="It was fierce and overwhelming: it hid the far hills, hammered on the roof, and turned the track into streams.",g="1 mark for a valid point (very heavy, powerful, noisy). 1 mark for evidence (roaring curtain / hid the far hills / hammered on the roof / silver ropes / brown streams)."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up paragraph 6?",opts=["The storm ended at once when the rain began.","The sheep ran away across the moor.","The storm stayed over the moor for a while and then slowly moved away.","The narrator and Dad walked home in the rain."],a="C"),
 dict(d="2d",k="short",m=1,q="How can you tell that the narrator enjoyed the smell of the rain?",a="They breathed it in until their chest ached, and describe it as rich and sweet.",g="Accept: breathed it in until chest ached / rich and sweet."),
 dict(d="2a",k="find",m=1,q="Find and copy one word from paragraph 4 that means “very clear and bright”.",a="vivid",g="Accept “vivid” only."),
 dict(d="2e",k="short",m=1,q="What do you think Dad and the narrator will do next? Give a reason from the text.",a="They will leave the barn and walk out to look at the moor, because Dad says, “Let’s see what the moor looks like now.”",g="Accept any sensible prediction supported by the last lines."),
])
